/* Dashboard (avond) · «Aan het kijken» als één serie per keer, liggend, swipebaar met bolletjes: zes ontwerpen · 18 okt. */
(() => {
  const world = document.getElementById("world");
  const IM = {"dd": "data:image/webp;base64,", "ng": "data:image/webp;base64,"};
  const SKY = "linear-gradient(180deg,#ff9b5c 0%,#f2697a 45%,#c4508f 100%)";
  const css = `
  .wk-opts{display:grid;grid-template-columns:repeat(3,560px);gap:44px 30px}
  .wk-sky{width:560px;height:290px;border-radius:26px;background:${SKY};padding:36px 40px;font-family:Inter,system-ui,sans-serif;color:#fff;position:relative;overflow:hidden}
  .wk-panel{position:relative;width:480px;height:216px;border-radius:24px;background:rgba(255,255,255,.2);box-shadow:inset 0 0 0 1px rgba(255,255,255,.42);backdrop-filter:blur(14px);overflow:hidden}
  .wk-lbl{position:absolute;left:18px;top:16px;font-size:11.5px;font-weight:800;letter-spacing:.08em;color:rgba(255,255,255,.88);z-index:3}
  .wk-dots{position:absolute;display:flex;gap:6px;z-index:3}
  .wk-dots i{width:6px;height:6px;border-radius:999px;background:rgba(255,255,255,.5)}
  .wk-dots i.on{width:18px;background:#fff}
  .wk-title{font-size:24px;font-weight:800;letter-spacing:-.02em;line-height:1.05;text-shadow:0 2px 10px rgba(60,20,40,.35)}
  .wk-ep{font-size:12.5px;font-weight:700;opacity:.9;margin-top:6px}
  .wk-pill{display:inline-flex;align-items:center;gap:5px;height:24px;padding:0 10px;border-radius:999px;background:rgba(255,255,255,.24);box-shadow:inset 0 0 0 1px rgba(255,255,255,.4);font-size:11.5px;font-weight:800}
  .wk-bar{height:4px;border-radius:999px;background:rgba(255,255,255,.3);overflow:hidden}.wk-bar i{display:block;height:100%;width:58%;background:#fff;border-radius:999px}
  `;
  const dots = (pos) => `<span class="wk-dots" style="${pos}"><i class="on"></i><i></i></span>`;
  const play = '<svg viewBox="0 0 24 24" width="11" height="11" fill="currentColor"><path d="M7 4.5v15l12-7.5z"/></svg>';
  const sky = (inner) => `<div class="wk-sky"><div class="wk-panel">${inner}</div></div>`;
  // Posters liggend bijgesneden (in de app: de TMDB-achtergrondfoto, die al liggend is).
  const img = (k, style) => `<img src="${IM[k]}" alt="" style="position:absolute;object-fit:cover;${style}">`;

  const W = [
    ["W1", "Fade naar links", "De foto vult de rechterkant en vervaagt via een zacht masker naar links in het glas, waar titel, aflevering en voortgang staan. Bolletjes linksonder.",
      sky(`${img("dd", "right:0;top:0;width:72%;height:100%;object-position:50% 22%;-webkit-mask-image:linear-gradient(90deg,transparent 0%,#000 55%);mask-image:linear-gradient(90deg,transparent 0%,#000 55%)")}
        <span class="wk-lbl">AAN HET KIJKEN</span>
        <div style="position:absolute;left:18px;bottom:40px;z-index:3;max-width:56%"><div class="wk-title">Daredevil:<br>Born Again</div><div class="wk-ep">Seizoen 2 · Aflevering 7</div></div>
        <div style="position:absolute;left:18px;bottom:22px;width:150px;z-index:3" class="wk-bar"><i></i></div>${dots("right:16px;bottom:16px")}`)],
    ["W2", "Vignet in het glas", "De foto vult het hele paneel maar loopt aan alle randen uit in het glas (radiaal masker), alsof ze erin zweeft. Titel onderaan op een zachte schaduw, bolletjes in het midden.",
      sky(`${img("ng", "inset:0;width:100%;height:100%;object-position:50% 25%;-webkit-mask-image:radial-gradient(75% 85% at 55% 40%,#000 45%,transparent 100%);mask-image:radial-gradient(75% 85% at 55% 40%,#000 45%,transparent 100%)")}
        <span style="position:absolute;inset:auto 0 0 0;height:60%;background:linear-gradient(180deg,transparent,rgba(110,30,60,.45));z-index:2"></span>
        <span class="wk-lbl">AAN HET KIJKEN</span>
        <div style="position:absolute;left:18px;bottom:34px;z-index:3"><div class="wk-title">Neagley</div><div class="wk-ep">Seizoen 1 · Aflevering 8 · nieuw</div></div>${dots("left:50%;transform:translateX(-50%);bottom:14px")}`)],
    ["W3", "Kaart met gloed", "Een liggende kaart (16:9) links, met dezelfde foto wazig en uitvergroot erachter: de kleuren gloeien uit in het glas. Rechts titel, aflevering en een speelknop.",
      sky(`${img("dd", "left:-10%;top:-30%;width:80%;height:160%;filter:blur(30px) saturate(1.6);opacity:.75;-webkit-mask-image:radial-gradient(closest-side,#000,transparent);mask-image:radial-gradient(closest-side,#000,transparent)")}
        <span class="wk-lbl">AAN HET KIJKEN</span>
        <span style="position:absolute;left:18px;top:46px;width:210px;height:118px;border-radius:16px;overflow:hidden;box-shadow:0 14px 26px -12px rgba(60,10,20,.7),0 0 0 1px rgba(255,255,255,.25);z-index:2">${img("dd", "inset:0;width:100%;height:100%;object-position:50% 20%")}</span>
        <div style="position:absolute;left:246px;top:52px;right:16px;z-index:3"><div class="wk-title" style="font-size:21px">Daredevil:<br>Born Again</div><div class="wk-ep">S2 · A7</div><span class="wk-pill" style="margin-top:12px">${play} Verder kijken</span></div>${dots("left:18px;bottom:16px")}`)],
    ["W4", "Duotone in de lucht", "De foto in de kleuren van de avondlucht (zwart-wit + warme kleurlaag) en onderaan uitgevaagd: het beeld smelt in de zonsondergang. Grote witte titel, bolletjes rechtsonder.",
      sky(`<span style="position:absolute;inset:0;-webkit-mask-image:linear-gradient(180deg,#000 30%,transparent 100%);mask-image:linear-gradient(180deg,#000 30%,transparent 100%)">${img("ng", "inset:0;width:100%;height:100%;object-position:50% 24%;filter:grayscale(1) contrast(1.15) brightness(1.05)")}<span style="position:absolute;inset:0;background:linear-gradient(135deg,#ff9b5c,#c4508f);mix-blend-mode:multiply;opacity:.85"></span></span>
        <span class="wk-lbl">AAN HET KIJKEN</span>
        <div style="position:absolute;left:18px;bottom:22px;z-index:3"><div class="wk-title" style="font-size:30px">Neagley</div><div class="wk-ep">Seizoen 1 · Aflevering 8</div></div>${dots("right:18px;bottom:20px")}`)],
    ["W5", "Volgende piept", "De huidige serie als grote liggende kaart die onderaan in het glas vervaagt; rechts piept de volgende serie (half zichtbaar) als hint om te swipen. Bolletjes onder de kaart.",
      sky(`<span class="wk-lbl">AAN HET KIJKEN</span>
        <span style="position:absolute;left:18px;top:42px;width:340px;height:140px;border-radius:18px;overflow:hidden;box-shadow:0 0 0 1px rgba(255,255,255,.3)">${img("dd", "inset:0;width:100%;height:100%;object-position:50% 20%;-webkit-mask-image:linear-gradient(180deg,#000 45%,transparent 100%);mask-image:linear-gradient(180deg,#000 45%,transparent 100%)")}<span style="position:absolute;left:14px;bottom:12px"><span class="wk-title" style="font-size:19px;display:block">Daredevil: Born Again</span><span class="wk-ep" style="display:block;margin-top:3px">S2 · A7</span></span></span>
        <span style="position:absolute;left:370px;top:54px;width:160px;height:116px;border-radius:16px;overflow:hidden;opacity:.75;box-shadow:0 0 0 1px rgba(255,255,255,.3)">${img("ng", "inset:0;width:100%;height:100%;object-position:50% 25%;-webkit-mask-image:linear-gradient(90deg,#000 30%,transparent 95%);mask-image:linear-gradient(90deg,#000 30%,transparent 95%)")}</span>${dots("left:18px;bottom:14px")}`)],
    ["W6", "Cinemastrook", "Breedbeeld: een scherpe filmstrook in het midden, erboven en eronder dezelfde foto wazig die in het glas overloopt. Titel en aflevering met een voortgangsbalk eronder.",
      sky(`${img("ng", "inset:0;width:100%;height:100%;object-position:50% 30%;filter:blur(18px) saturate(1.4);opacity:.6")}
        <span style="position:absolute;inset:0;background:rgba(255,255,255,.08)"></span>
        <span class="wk-lbl">AAN HET KIJKEN</span>
        <span style="position:absolute;left:0;right:0;top:44px;height:96px;overflow:hidden;box-shadow:0 10px 20px -10px rgba(60,10,30,.6);-webkit-mask-image:linear-gradient(90deg,transparent,#000 12%,#000 88%,transparent);mask-image:linear-gradient(90deg,transparent,#000 12%,#000 88%,transparent)">${img("ng", "inset:0;width:100%;height:100%;object-position:50% 28%")}</span>
        <div style="position:absolute;left:18px;right:18px;bottom:18px;z-index:3;display:flex;align-items:flex-end;justify-content:space-between;gap:12px"><div><div class="wk-title" style="font-size:20px">Neagley</div><div class="wk-ep" style="margin-top:3px">S1 · A8</div><div class="wk-bar" style="width:170px;margin-top:8px"><i></i></div></div><span class="wk-dots" style="position:static"><i class="on"></i><i></i></span></div>`)],
  ];

  const b = document.createElement("section");
  b.className = "board iter";
  b.style.cssText = "left:0;top:0;width:1780px";
  b.innerHTML = `<style>${css}</style><header class="bhd"><span class="bnum">WK</span><div><h2>Dashboard · «Aan het kijken», één serie per keer <span class="tag">6 ontwerpen · avond · 18 okt</span></h2><p>Eén serie tegelijk in liggend formaat; met meer series swipe je verder (bolletjes onderaan). Glasachtergrond blijft, met telkens een andere manier waarop het beeld in het glas uitvloeit.</p><p class="uses">Bouwt op: dashboard avond · C1 Avondrood</p></div></header>
    <div class="wk-opts">${W.map(([k, n, why, html]) => `<div class="dk-opt"><div class="ag-opthd"><span class="ag-key">${k}</span><div><h3>${n}</h3><p>${why}</p></div></div>${html}</div>`).join("")}</div>`;
  world.appendChild(b);
  const others = [...world.children].filter((el) => el !== b && el.tagName === "SECTION");
  const topY = Math.min(...others.map((el) => el.offsetTop));
  b.style.top = `${topY - 240 - b.offsetHeight}px`;
})();
